import{_ as e,o as c,c as d,a2 as t}from"./chunks/framework.CvydjLy7.js";const _=JSON.parse('{"title":"11.11 小结与下一步","description":"","frontmatter":{"title":"11.11 小结与下一步"},"headers":[],"relativePath":"ch11/11.md","filePath":"ch11/11.md","lastUpdated":1789497795000}'),a={name:"ch11/11.md"};function r(n,o,s,l,i,g){return c(),d("div",null,[...o[0]||(o[0]=[t('<h1 id="_11-11-小结与下一步" tabindex="-1">11.11 小结与下一步 <a class="header-anchor" href="#_11-11-小结与下一步" aria-label="Permalink to &quot;11.11 小结与下一步&quot;">​</a></h1><p>这一篇从 <code>mvn package</code> 的产物一路走到原生可执行文件：</p><ul><li><strong>可执行 jar 的结构</strong>：<code>BOOT-INF/lib</code> 塞了 99.6% 的体积，<code>Main-Class</code> 指向 <code>loader.launch.JarLauncher</code> 而不是你的主类，原因是 JDK 不认识嵌套 jar；<code>loader</code> 下的 <code>launch</code> 包名是 Boot 3.2 之后才有的</li><li><strong>4.x 的 jarmode 换成了 <code>tools</code></strong>：<code>layertools</code> 已不存在；<code>extract --layers</code> 默认不带启动器，产出的是靠 <code>Class-Path</code> 启动的薄 jar，必须把四层拼到同一目录才能跑</li><li><strong>分层按变化频率切</strong>：<code>dependencies</code> / <code>spring-boot-loader</code> / <code>snapshot-dependencies</code> / <code>application</code>，顺序就是往镜像里添加的顺序</li><li><strong>解压能提速</strong>：实测启动从 4.80 秒降到 3.77 秒，省掉的是嵌套 jar 的展开与自定义类加载</li><li><strong>JVM 上的 AOT</strong>：<code>-Pnative package</code> 触发 <code>process-aot</code>，219 个 Bean 定义源文件编译进产物；必须加 <code>-Dspring.aot.enabled=true</code> 才生效（实测 4.80 → 3.87 秒）；限制是 Bean 定义不能在运行期变</li><li><strong>4.x 的提示文件换了格式</strong>：不再生成 <code>reflect-config.json</code> 等五个文件，而是统一的 <code>reachability-metadata.json</code>，这一点和官方文档现有表述不一致</li><li><strong>CDS</strong>：训练运行 + 归档，实测 3.77 → 2.28 秒；与 AOT 叠加是 1.65 秒，比基线快 66%；代价是 111MB 的归档和“必须在目标平台生成”的约束</li><li><strong>容器化的两个细节</strong>：<code>COPY --chown</code> 与 <code>COPY</code> + <code>RUN chown</code> 差 64MB（CDS 场景下差 180MB）；分层不减小镜像体积，减少的是改动后的重建量</li><li><strong>容器内实测</strong>：单层 4.81 秒、分层 3.98 秒、分层加 CDS 2.29 秒，非 root 用户 10001 运行正常</li><li><strong>Buildpacks</strong>：<code>mvn spring-boot:build-image</code> 一条命令出镜像，默认 builder 是 <code>paketobuildpacks/builder-noble-java-tiny</code>；省事但控制力弱</li><li><strong>GraalVM 原生镜像</strong>：本机实测编译 4 分 37 秒，产出 191MB 可执行文件，启动 0.268 秒（JVM 是 4.80 秒），内存 167MB（JVM 是 546MB）；限制来自封闭世界假设</li><li><strong>上线前的一批配置</strong>：配置走环境变量而不是烤进镜像、容器内存感知与 <code>JAVA_TOOL_OPTIONS</code>、优雅停机、日志走标准输出、密钥不进镜像</li></ul><p>到这里，后端从写代码到交付的整条链路走通了。可下一次打开浏览器，还是只有 <code>curl</code> 能用——<strong>用户看到的界面还不存在</strong>。</p><p>下一篇开始全端实战。前端部分会从零搭一个 Vue 3 + Element Plus 的管理端，把这一路写下来的 REST 接口接上去：活动列表与分页、文件上传、登录与令牌续期、路由守卫。接口的形态在前 11 篇里已经固定了（统一响应体 <code>ApiResponse</code>、分页 <code>PageResult</code>、JWT 在 <code>Authorization</code> 头），前端要做的就是把它们串起来。</p>',5)])])}const u=e(a,[["render",r]]);export{_ as __pageData,u as default};
